import{_ as o,o as t,c as a,a5 as s}from"./chunks/framework.CsGesDJn.js";const f=JSON.parse('{"title":"3.2.9 Deactivate Account","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-9-deactivate-account/spec.md","filePath":"feature/authentication/3-2-9-deactivate-account/spec.md"}'),i={name:"feature/authentication/3-2-9-deactivate-account/spec.md"};function c(d,e,n,r,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-2-9-deactivate-account" tabindex="-1">3.2.9 Deactivate Account <a class="header-anchor" href="#_3-2-9-deactivate-account" aria-label="Permalink to &quot;3.2.9 Deactivate Account&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.2.9</td></tr><tr><td>Feature</td><td>Deactivate Account</td></tr><tr><td>Domain</td><td>Authentication (FR 3.2)</td></tr><tr><td>Role</td><td>Any signed-in USER, for their own account</td></tr><tr><td>Version</td><td>3.0 — 2026-09-25 — re-verified against AuthController/AuthServiceImpl: BR-22 token blacklist is now real code (<code>accessToken</code>/<code>refreshToken</code> params added to <code>deactivate()</code>, both blacklisted via <code>JwtUtil</code> after status update); BR-23 confirmed satisfied by the existing <code>AGENCY_OWNERSHIP_ACTIVE</code> guard, which was not changed this session — only the appendix wording around it. OTP resend-cooldown gap (previous v2.0 note) still open, unchanged.</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a signed-in user activates &quot;Deactivate&quot; in the Danger Zone of the profile screen (<code>/profile</code>) and confirms the dialog with their password, or, for an account with no password, with a one-time code sent to their email.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> USER who is signed in, either with a password or as an OAuth-only account (<code>passwordHash == null</code>, e.g. created through Google) with no password.</li><li><strong>Purpose:</strong> Let a user disable their own account (soft delete — no row is removed) after proving identity with the password or with a one-time email code, and immediately cut off their active sessions.</li><li><strong>Interface:</strong> Danger Zone section on <code>/profile</code> with a confirmation dialog. Accounts with a password show a password field. Accounts without a password show a &quot;Send code&quot; button and, once sent, a six-digit code field.</li><li><strong>Data Processing:</strong> <code>AuthController.deactivate</code> resolves the caller from the Bearer access token, reads the <code>refreshToken</code> cookie, and reads the raw access token from the <code>Authorization</code> header. <code>AuthServiceImpl.deactivate</code> loads the user, verifies identity via the password or OTP branch, checks the caller does not own any ACTIVE agency, sets <code>user.status = DEACTIVATED</code> and saves, then blacklists the caller&#39;s access token and refresh token (best-effort) so active sessions are cut off immediately.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Deactivate Account (<code>/profile</code>, Danger Zone), grounded in <code>brandhub-web-dashboard/src/pages/profile/index.tsx</code>:</p><ul><li>A red-bordered &quot;Danger Zone&quot; card with a warning icon, a hint line, and a &quot;Deactivate&quot; button (<code>profile.danger.deactivateButton</code>) that opens the confirm dialog (<code>deactivateOpen</code>).</li><li>If the account has a password (<code>hasPassword</code>): the dialog shows a password <code>Input</code> (<code>deactivatePassword</code>).</li><li>If the account has no password: the dialog shows a &quot;Send code&quot; / &quot;Resend code&quot; <code>Button</code> (<code>handleSendDeactivateOtp</code>, loading state <code>sendingOtp</code>) followed by an OTP <code>Input</code> (<code>deactivateOtp</code>).</li><li>Cancel and a destructive &quot;Confirm Deactivate&quot; button (<code>handleDeactivate</code>); the confirm button is disabled until the relevant field (password or OTP) is non-empty, or while the request is in flight (<code>deactivating</code>).</li><li>On success the client clears the local session and returns to <code>/login</code>.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> Bearer access token (<code>Authorization</code> header). Exactly one of <code>password</code> or <code>otpCode</code>, selected by the account&#39;s own state (<code>user.passwordHash == null</code>), not by which field the client sends.</li><li><strong>Input optional:</strong> <code>DeactivateRequest(password, otpCode)</code> — both fields are optional at the DTO level (no <code>@Valid</code> constraint on either); the service enforces which one is actually required based on account type, and ignores the other. <code>refreshToken</code> cookie is optional (its absence just skips the refresh-token blacklist step).</li><li><strong>System data:</strong> <code>userId</code> (from token), <code>user.passwordHash</code>, <code>user.status</code>, Redis key <code>otp:deactivate:{userId}</code> (OTP value, TTL 10 min), agencies owned by the user and their <code>status</code>, the caller&#39;s raw access token (from the <code>Authorization</code> header) and refresh token (from the <code>refreshToken</code> cookie).</li><li><strong>Output:</strong> <code>ApiResponse&lt;Void&gt;</code> — no payload, 200 OK.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-22:</strong> Account deactivation sets <code>user.status = UserStatus.DEACTIVATED</code> and blacklists outstanding tokens so active sessions are cut off; reversible unless decided otherwise (TBD). Implemented in <code>AuthServiceImpl.deactivate()</code>: after <code>user.setStatus(DEACTIVATED)</code> / <code>save(user)</code>, the method blacklists the caller&#39;s access token (from the <code>Authorization</code> header, passed through by <code>AuthController</code>) and refresh token (from the <code>refreshToken</code> cookie) via <code>jwtUtil.blacklistToken(...)</code>, each wrapped in a best-effort try/catch that ignores <code>JwtException</code> for a malformed or absent token. A subsequent login or refresh is also rejected by <code>checkStatus()</code> with 403 <code>ACCOUNT_DEACTIVATED</code>, but the blacklist call is what makes cut-off immediate rather than only on next refresh/expiry.</li><li><strong>BR-23:</strong> The last active OWNER of an Agency cannot self-deactivate. <code>OWNER</code> is an Agency-level role only (workspace <code>MemberRole</code> has no <code>OWNER</code>), so the enforcement point is the Agency-ownership check: after identity is confirmed, <code>AuthServiceImpl.deactivate()</code> checks <code>agencyRepository.findByOwnerId(userId)</code> for any Agency with <code>status == ACTIVE</code>. If one exists → 409 <code>AGENCY_OWNERSHIP_ACTIVE</code>, account left unchanged; ownership must be transferred first. This guard existed prior to this session and is unchanged; what changed is only the shared understanding that it is BR-23&#39;s real enforcement (the appendix&#39;s own wording has already been corrected to say &quot;Agency&quot; rather than &quot;workspace&quot; and cites this same guard).</li><li><strong>Identity confirmation (implements BR-22&#39;s precondition):</strong> the account itself selects the branch — <code>user.passwordHash == null</code> → OTP branch (Redis key <code>otp:deactivate:{userId}</code>; missing, expired, or mismatched code → 400 <code>OTP_INVALID</code>; a match deletes the key so it cannot be reused). <code>user.passwordHash != null</code> → password branch (<code>passwordEncoder.matches</code> mismatch → 400 <code>WRONG_CURRENT_PASSWORD</code>). Whichever field does not match the branch is ignored.</li><li><strong><code>sendDeactivateOtp</code> (OTP delivery):</strong> generates a 6-digit OTP, stores it in Redis (<code>otp:deactivate:{userId}</code>, TTL 10 min), sends it via <code>MailService.sendOtpEmail</code>. <ul><li>⚠ <strong>BA conflict (needs team decision):</strong> <code>sendDeactivateOtp</code> has no resend cooldown/rate-limit check. This is asymmetric with the analogous email-OTP flow (<code>resendOtp</code>, 60s cooldown via Redis key <code>otp:resend:{email}</code>) and the phone-OTP flow (<code>linkPhone</code>, 60s cooldown via <code>phone:otp:resend:{userId}</code>), both of which do check a cooldown before issuing a new code. Likely an oversight rather than an intentional design difference. Unchanged this session.</li></ul></li><li>Missing/malformed Bearer token → 401 <code>INVALID_CREDENTIALS</code> (via <code>requireUserId</code>).</li><li>Account referenced by the token no longer exists → 404 <code>USER_NOT_FOUND</code>.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Missing or malformed access token → 401 <code>INVALID_CREDENTIALS</code>, toast MSG22.</li><li><code>password</code> empty (password branch) → Display: <strong>MSG02</strong>.</li><li><code>otpCode</code> empty or malformed (OTP branch) → Display: <strong>MSG02</strong>.</li></ul><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>User opens the Danger Zone on <code>/profile</code> and activates &quot;Deactivate&quot;.</li><li>Client resolves whether the account has a password (<code>hasPassword</code>) and shows the matching field.</li><li>For an OAuth-only account, the user first clicks &quot;Send code&quot; → <code>POST /api/v1/auth/deactivate/send-otp</code> → <code>sendDeactivateOtp</code> generates and emails a 6-digit OTP (Redis TTL 10 min).</li><li>The user supplies the password or the OTP and confirms → <code>POST /api/v1/auth/deactivate { password?, otpCode? }</code>, with the <code>Authorization: Bearer &lt;accessToken&gt;</code> header and (if present) the <code>refreshToken</code> cookie sent automatically by the browser.</li><li><code>AuthController.deactivate</code> resolves the caller (<code>requireUserId</code>), extracts the raw access token from the header and the refresh token from the cookie.</li><li><code>deactivate</code> loads the user (404 <code>USER_NOT_FOUND</code> if missing) and verifies the password or the OTP depending on <code>passwordHash</code>.</li><li><code>deactivate</code> checks <code>agencyRepository.findByOwnerId(userId)</code> for an ACTIVE agency (BR-23); none found.</li><li><code>deactivate</code> sets <code>user.status = DEACTIVATED</code> and saves.</li><li><code>deactivate</code> blacklists the access token and, if present, the refresh token via <code>jwtUtil.blacklistToken(...)</code> (BR-22), ignoring failures on a malformed/absent token.</li><li>200 OK, no payload; client clears the local session, redirects to <code>/login</code>, toast MSG91 (&quot;Account deactivated successfully.&quot;).</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>5.a1: Missing or invalid access token → 401 <code>INVALID_CREDENTIALS</code>, toast MSG22. 5.a2: The user signs in again.</li><li>6.a1: Account referenced by the token no longer exists → 404 <code>USER_NOT_FOUND</code>, toast MSG38. 6.a2: The user signs in again with a valid account.</li><li>6.b1: Password branch, wrong password → 400 <code>WRONG_CURRENT_PASSWORD</code>, Display: <strong>MSG19</strong>. 6.b2: The user re-enters the password.</li><li>6.c1: OTP branch — code missing, expired (&gt;10 min), never requested, or mismatched → 400 <code>OTP_INVALID</code>, Display: <strong>MSG20</strong>. 6.c2: The user requests a new code (no cooldown enforced — see BA conflict above) and re-enters it.</li><li>7.a1: The user owns at least one ACTIVE agency (BR-23) → 409 <code>AGENCY_OWNERSHIP_ACTIVE</code>, toast MSG38. 7.a2: The user transfers agency ownership first; if the OTP branch was used, the OTP has already been consumed, so a new code must be requested before retrying.</li><li>9.a1: Access token is malformed, expired, or absent when <code>deactivate()</code> reaches the blacklist step → <code>jwtUtil.blacklistToken</code> throws <code>JwtException</code>, caught and ignored; deactivation still succeeds (status is already saved at step 8). 9.a2: Same handling for a malformed/absent <code>refreshToken</code> cookie — no user-visible error either way, this is a best-effort cleanup step after the account state change already committed.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li><code>user.status = DEACTIVATED</code>; all related rows (agencies, workspace memberships, etc.) are kept — this is a soft delete.</li><li>The OTP, when the OTP branch was used, is consumed (Redis key deleted) and cannot be reused.</li><li>The caller&#39;s access token and refresh token (if present) are blacklisted via <code>JwtUtil</code>, so the currently active session is cut off immediately, not just on next refresh attempt.</li><li>A subsequent login or refresh attempt is also rejected with 403 <code>ACCOUNT_DEACTIVATED</code> (<code>checkStatus()</code>), independent of the blacklist.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Reactivating a deactivated account (no endpoint in <code>AuthController</code> for this; TBD per BR-22&#39;s &quot;reversible unless decided otherwise&quot;).</li><li>Deleting the account&#39;s data (deactivation is a soft delete only).</li><li>OTP resend cooldown on <code>sendDeactivateOtp</code> (see BA conflict above).</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p>Section5_Requirement_Appendix.md (BR-22, BR-23, MSG02, MSG19, MSG20, MSG91) — read-only, not modified.</p>',26)])])}const p=o(i,[["render",c]]);export{f as __pageData,p as default};
